package com.odikyu.app

import com.odikyu.app.data.encode
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Pins the Kotlin tokenizer to the Python reference implementation
 * (ml/message-classifier/preprocess.py). Expected IDs were generated by running
 * that script against the shipped vocab.txt — if either side drifts, this fails.
 */
class TokenizerTest {

    private val vocab: Map<String, Int> by lazy {
        val file = generateSequence(File(".").absoluteFile.parentFile) { it.parentFile }
            .map { File(it, "src/main/assets/classifier/vocab.txt") }
            .firstOrNull { it.exists() }
            ?: error("vocab.txt not found above ${File(".").absolutePath}")
        file.readLines().mapIndexed { i, token -> token to i }.toMap()
    }

    @Test
    fun `bank notification matches python reference ids`() {
        // python: encode("Your A/C debited by INR 500.00 on 31/10/25. New Bal INR 6578.63", ...)
        // digit runs are masked to '#' before lookup (500.00 -> # #, dates -> #).
        val ids = encode(
            "Your A/C debited by INR 500.00 on 31/10/25. New Bal INR 6578.63",
            vocab,
            maxLen = 64,
        )
        assertArrayEquals(intArrayOf(3, 9, 10, 18, 25, 23, 2, 2, 5, 2, 2, 2), ids.copyOf(12))
        assertEquals(64, ids.size)
        // 17 real tokens, everything after is PAD.
        ids.slice(17 until 64).forEach { assertEquals(0, it) }
    }

    @Test
    fun `phishing-style message matches python reference ids`() {
        // python: "URGENT: your account will be blocked!! click bit.ly/xYz now"
        val ids = encode(
            "URGENT: your account will be blocked!! click bit.ly/xYz now",
            vocab,
            maxLen = 64,
        )
        assertArrayEquals(
            intArrayOf(84, 3, 38, 191, 112, 190, 36, 801, 842, 59, 17, 0),
            ids.copyOf(12),
        )
        assertEquals(11, ids.indexOfFirst { it == 0 })
    }

    @Test
    fun `unknown tokens fall back to UNK id 1`() {
        // python: "zzz-unknown-token-xyzzy 42" -> [1, 2591, 1, 1, 2, 0, ...]
        val ids = encode("zzz-unknown-token-xyzzy 42", vocab, maxLen = 64)
        assertArrayEquals(intArrayOf(1, 2591, 1, 1, 2), ids.copyOf(5))
        assertEquals(0, ids[5])
    }

    @Test
    fun `caps at max_len and pads the remainder`() {
        val ids = encode("one two three four five six", vocab, maxLen = 4)
        assertEquals(4, ids.size)
        assertEquals(vocab["one"], ids[0])
        assertEquals(vocab["four"], ids[3])

        val short = encode("hi", vocab, maxLen = 8)
        assertEquals(8, short.size)
        assertEquals(vocab["hi"], short[0])
        short.slice(1 until 8).forEach { assertEquals(0, it) }
    }

    @Test
    fun `tokenizes exactly like the python tokenizer`() {
        // python: re.sub(r"\d+", "#", text.lower()) then re.findall(r"[a-z#]+", masked)
        val cases = mapOf(
            "Hello, World!" to listOf("hello", "world"),
            "A/C debited INR500.00" to listOf("a", "c", "debited", "inr#", "#"),
            "bit.ly/abc_XYZ-123" to listOf("bit", "ly", "abc", "xyz", "#"),
            "OTP 492813 valid" to listOf("otp", "#", "valid"),
            "!!!" to emptyList(),
            "" to emptyList(),
        )
        cases.forEach { (text, expected) ->
            val decoded = TOKEN_PATTERN
                .findAll(DIGIT_RUN.replace(text.lowercase(), "#"))
                .map { it.value }
                .toList()
            assertEquals("tokenize($text)", expected, decoded)
        }
        assertTrue(vocab["your"] == 3)
        assertTrue("#" in vocab)
    }

    companion object {
        private val DIGIT_RUN = Regex("\\d+")
        private val TOKEN_PATTERN = Regex("[a-z#]+")
    }
}
